// 지구과학 탐험 — 메인 앱. 페이지 전환 + 학습 진행률 + 공용 우주 배경/레이아웃.
import React, { useState } from 'react';
import Home from './pages/Home';
import EarthInterior from './pages/EarthInterior';
import AtmosphereExplorer from './pages/AtmosphereExplorer';
import SystemsLab from './pages/SystemsLab';
import Quiz from './pages/Quiz';
import Navigation from './components/Navigation';
import Starfield from './components/Starfield';

export type PageType = 'home' | 'interior' | 'atmosphere' | 'lab' | 'quiz';
export type LessonPage = Exclude<PageType, 'home'>;

const LESSON_PAGES: LessonPage[] = ['interior', 'atmosphere', 'lab', 'quiz'];

export default function App() {
  const [currentPage, setCurrentPage] = useState<PageType>('home');
  const [completedTopics, setCompletedTopics] = useState<LessonPage[]>([]);

  const markComplete = (topic: LessonPage) => {
    setCompletedTopics((prev) => (prev.includes(topic) ? prev : [...prev, topic]));
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'interior': return <EarthInterior onComplete={() => markComplete('interior')} />;
      case 'atmosphere': return <AtmosphereExplorer onComplete={() => markComplete('atmosphere')} />;
      case 'lab': return <SystemsLab onComplete={() => markComplete('lab')} />;
      case 'quiz': return <Quiz onComplete={() => markComplete('quiz')} />;
      default: return <Home completedTopics={completedTopics} onSelectTopic={setCurrentPage} />;
    }
  };

  return (
    <div className="relative w-full h-screen flex flex-col overflow-hidden bg-gradient-to-b from-[#05070f] via-[#070b1a] to-[#0a0f24] text-white">
      <Starfield />
      <div className="relative z-10 flex flex-col h-full min-h-0">
        <Navigation
          currentPage={currentPage}
          completedTopics={completedTopics}
          totalLessons={LESSON_PAGES.length}
          onNavigate={setCurrentPage}
        />
        <main className="flex-1 min-h-0">{renderPage()}</main>
      </div>
    </div>
  );
}

