export function getInteriorLayerByDepth(depth: number): InteriorLayer {
  return interiorLayers.find((layer) => depth >= layer.depthStart && depth <= layer.depthEnd) ?? interiorLayers[interiorLayers.length - 1];
}

export function getAtmosphereLayerByAltitude(altitude: number): AtmosphereLayer {
  return atmosphereLayers.find((layer) => altitude >= layer.altitudeStart && altitude <= layer.altitudeEnd) ?? atmosphereLayers[atmosphereLayers.length - 1];
}

