// 고도 탐침(슬라이더 연동) 아크, 대표 현상(구름·오존·유성·오로라·위성)을 표시.
import React, { useEffect, useRef } from 'react';
import { AtmosphereLayer, AtmosphereLayerId } from '../data/earthScience';

interface AtmosphereViewProps {
  layers: AtmosphereLayer[];
  selectedId: AtmosphereLayerId | null;
  probeDisplay: number;   // 0 ~ 100 (압축 고도 프로파일 위치)
  probeKm: number;        // 실제 고도(km) 라벨용
  onSelectLayer: (id: AtmosphereLayerId) => void;
}

const WIDTH = 720;
const HEIGHT = 560;
const CX = WIDTH / 2;
const EARTH_R = 1150;
const EARTH_CENTER_Y = 520 + EARTH_R;   // 지표(고도 0)가 y≈520
const ATM_H = 470;                       // display 0→100 이 차지하는 화면 두께(px)
const PHI_MAX = Math.asin((CX + 40) / EARTH_R);

interface SceneObject { emoji: string; label: string; display: number; ox: number; }
const OBJECTS: SceneObject[] = [
  { emoji: '☁️', label: '구름·비', display: 7, ox: -150 },
  { emoji: '✈️', label: '여객기', display: 12, ox: 120 },
  { emoji: '🎈', label: '기상 관측 기구', display: 33, ox: -160 },
  { emoji: '☄️', label: '유성', display: 54, ox: -80 },
  { emoji: '🛰️', label: '저궤도 위성·ISS', display: 78, ox: 40 },
];

function radiusFor(display: number) { return EARTH_R + (display / 100) * ATM_H; }
// display 값 + 수평 오프셋(px) → 화면 좌표
function project(display: number, ox: number) {
  const rad = radiusFor(display);
  const phi = ox / EARTH_R;
  return { x: CX + rad * Math.sin(phi), y: EARTH_CENTER_Y - rad * Math.cos(phi) };
}

export default function AtmosphereView({ layers, selectedId, probeDisplay, probeKm, onSelectLayer }: AtmosphereViewProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef(0);
  const tickRef = useRef(0);
  const propsRef = useRef({ layers, selectedId, probeDisplay, probeKm });
  propsRef.current = { layers, selectedId, probeDisplay, probeKm };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const ss = Math.min(3, Math.max(2, Math.round((window.devicePixelRatio || 1) * 1.5)));
    canvas.width = WIDTH * ss;
    canvas.height = HEIGHT * ss;

    const bandPath = (rInner: number, rOuter: number) => {
      ctx.beginPath();
      ctx.arc(CX, EARTH_CENTER_Y, rOuter, -Math.PI / 2 - PHI_MAX, -Math.PI / 2 + PHI_MAX, false);
      ctx.arc(CX, EARTH_CENTER_Y, rInner, -Math.PI / 2 + PHI_MAX, -Math.PI / 2 - PHI_MAX, true);
      ctx.closePath();
    };

    const render = () => {
      const { layers: lyrs, selectedId: selected, probeDisplay: probe, probeKm: km } = propsRef.current;
      tickRef.current += 1;
      const t = tickRef.current;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(ss, 0, 0, ss, 0, 0);

      // 대기층 밴드(바깥→안, 색이 위로 갈수록 어두워짐)
      for (let i = lyrs.length - 1; i >= 0; i -= 1) {
        const layer = lyrs[i];
        const rIn = radiusFor(layer.displayStart);
        const rOut = radiusFor(layer.displayEnd);
        const active = selected === layer.id;
        const grad = ctx.createRadialGradient(CX, EARTH_CENTER_Y, rIn, CX, EARTH_CENTER_Y, rOut);
        grad.addColorStop(0, layer.color);
        grad.addColorStop(1, shadeHex(layer.color, -0.35));
        bandPath(rIn, rOut);
        ctx.globalAlpha = active ? 0.95 : 0.72;
        ctx.fillStyle = grad;
        ctx.fill();
        ctx.globalAlpha = 1;
        // 경계선
        ctx.strokeStyle = active ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.18)';
        ctx.lineWidth = active ? 2 : 1;
        ctx.beginPath();
        ctx.arc(CX, EARTH_CENTER_Y, rOut, -Math.PI / 2 - PHI_MAX, -Math.PI / 2 + PHI_MAX, false);
        ctx.stroke();
        // 층 이름 (왼쪽)
        const labelPt = project((layer.displayStart + layer.displayEnd) / 2, -CX + 8);
        ctx.font = active ? '700 14px sans-serif' : '600 13px sans-serif';
        ctx.fillStyle = active ? '#ffffff' : 'rgba(226,232,240,0.85)';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(layer.name, labelPt.x, labelPt.y);
      }

      // 오존층 강조(성층권 하부)
      const ozone = project(29, 150);
      ctx.font = '600 11px sans-serif';
      ctx.fillStyle = 'rgba(191,219,254,0.9)';
      ctx.textAlign = 'center';
      ctx.fillText('🛡️ 오존층', ozone.x, ozone.y);

      // 오로라(열권) — 은은한 초록 셰이드
      const auroraY = radiusFor(70);
      ctx.save();
      ctx.globalAlpha = 0.28 + 0.12 * Math.sin(t * 0.05);
      const ag = ctx.createRadialGradient(CX, EARTH_CENTER_Y, radiusFor(64), CX, EARTH_CENTER_Y, radiusFor(80));
      ag.addColorStop(0, 'rgba(34,197,94,0)');
      ag.addColorStop(0.5, 'rgba(34,197,94,0.5)');
      ag.addColorStop(1, 'rgba(16,185,129,0)');
      bandPath(radiusFor(64), radiusFor(80));
      ctx.fillStyle = ag;
      ctx.fill();
      ctx.restore();
      const auroraPt = project(74, 120);
      ctx.globalAlpha = 1;
      ctx.font = '600 11px sans-serif';
      ctx.fillStyle = '#86efac';
      ctx.textAlign = 'center';
      ctx.fillText('🌌 오로라', auroraPt.x, auroraPt.y);

      // 대표 현상 오브젝트
      OBJECTS.forEach((obj) => {
        const p = project(obj.display, obj.ox);
        ctx.font = '20px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(obj.emoji, p.x, p.y);
        ctx.font = '600 10px sans-serif';
        ctx.fillStyle = 'rgba(226,232,240,0.85)';
        ctx.fillText(obj.label, p.x, p.y + 18);
      });

      // 지표(지구 표면)
      ctx.beginPath();
      ctx.arc(CX, EARTH_CENTER_Y, EARTH_R, -Math.PI / 2 - PHI_MAX, -Math.PI / 2 + PHI_MAX, false);
      ctx.lineTo(WIDTH, HEIGHT);
      ctx.lineTo(0, HEIGHT);
      ctx.closePath();
      const ground = ctx.createLinearGradient(0, 480, 0, HEIGHT);
      ground.addColorStop(0, '#166534');
      ground.addColorStop(1, '#052e16');
      ctx.fillStyle = ground;
      ctx.fill();

      // 고도 탐침 아크 + 라벨
      const pr = radiusFor(probe);
      ctx.save();
      ctx.strokeStyle = '#fde68a';
      ctx.setLineDash([6, 5]);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(CX, EARTH_CENTER_Y, pr, -Math.PI / 2 - PHI_MAX, -Math.PI / 2 + PHI_MAX, false);
      ctx.stroke();
      ctx.setLineDash([]);
      const marker = project(probe, 0);
      ctx.fillStyle = '#fde68a';
      ctx.beginPath();
      ctx.arc(marker.x, marker.y, 6, 0, Math.PI * 2);
      ctx.fill();
      ctx.font = '700 14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`고도 ${Math.round(km).toLocaleString()} km`, marker.x, marker.y - 14);
      ctx.restore();

      rafRef.current = requestAnimationFrame(render);
    };

    rafRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  const handleClick = (event: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = (event.clientX - rect.left) * (WIDTH / rect.width);
    const my = (event.clientY - rect.top) * (HEIGHT / rect.height);
    const rad = Math.hypot(mx - CX, my - EARTH_CENTER_Y);
    const display = ((rad - EARTH_R) / ATM_H) * 100;
    for (let i = 0; i < layers.length; i += 1) {
      if (display >= layers[i].displayStart && display <= layers[i].displayEnd) {
        onSelectLayer(layers[i].id);
        return;
      }
    }
  };

  return (
    <canvas
      ref={canvasRef}
      width={WIDTH}
      height={HEIGHT}
      className="w-full h-full max-h-full object-contain cursor-pointer"
      onClick={handleClick}
    />
  );
}

function shadeHex(hex: string, amount: number): string {
  const value = hex.replace('#', '');
  const r = parseInt(value.substring(0, 2), 16);
  const g = parseInt(value.substring(2, 4), 16);
  const b = parseInt(value.substring(4, 6), 16);
  const adjust = (channel: number) => {
    const next = amount >= 0 ? channel + (255 - channel) * amount : channel * (1 + amount);
    return Math.max(0, Math.min(255, Math.round(next)));
  };
  return `rgb(${adjust(r)}, ${adjust(g)}, ${adjust(b)})`;
}

