// 자기장 세기·태양풍·오로라 값(0~1)에 따라 실시간으로 달라진다.
import React, { useEffect, useRef } from 'react';

interface MagnetosphereProps {
  fieldStrength: number;   // 0~1
  solarWind: number;       // 0~1
  auroraIntensity: number; // 0~1
}

const WIDTH = 640;
const HEIGHT = 440;
const CX = 400;
const CY = 220;
const EARTH_R = 46;
const PARTICLES = 70;

interface Particle { x: number; y: number; v: number; }

export default function Magnetosphere({ fieldStrength, solarWind, auroraIntensity }: MagnetosphereProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef(0);
  const tickRef = useRef(0);
  const particlesRef = useRef<Particle[]>([]);
  const propsRef = useRef({ fieldStrength, solarWind, auroraIntensity });
  propsRef.current = { fieldStrength, solarWind, auroraIntensity };

  if (particlesRef.current.length === 0) {
    const list: Particle[] = [];
    for (let i = 0; i < PARTICLES; i += 1) {
      list.push({ x: Math.random() * WIDTH, y: Math.random() * HEIGHT, v: 0.6 + Math.random() * 0.8 });
    }
    particlesRef.current = list;
  }

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const ss = Math.min(3, Math.max(2, Math.round((window.devicePixelRatio || 1) * 1.5)));
    canvas.width = WIDTH * ss;
    canvas.height = HEIGHT * ss;

    const render = () => {
      const { fieldStrength: field, solarWind: wind, auroraIntensity: aurora } = propsRef.current;
      tickRef.current += 1;
      const t = tickRef.current;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(ss, 0, 0, ss, 0, 0);

      // 자기권계면 정지점(자기장 강할수록 멀리, 태양풍 강할수록 압축)
      const standoff = EARTH_R * (2.2 + field * 3.4) * (1 - wind * 0.4);
      const boundaryX = CX - standoff;

      // 자기장선(쌍극자 루프) — 낮면(왼쪽) 압축, 밤면(오른쪽) 자기꼬리
      const lineCount = Math.round(2 + field * 5);
      ctx.lineWidth = 1.4;
      for (let i = 1; i <= lineCount; i += 1) {
        const spread = i / lineCount;
        ctx.strokeStyle = `rgba(96,165,250,${0.15 + field * 0.5 * (1 - spread * 0.4)})`;
        // 낮면(왼쪽) 루프
        const dayReach = standoff * (0.5 + spread * 0.55);
        ctx.beginPath();
        ctx.moveTo(CX, CY - EARTH_R);
        ctx.bezierCurveTo(CX - dayReach, CY - EARTH_R * 1.5, CX - dayReach, CY + EARTH_R * 1.5, CX, CY + EARTH_R);
        ctx.stroke();
        // 밤면(오른쪽) 자기꼬리
        const tailReach = standoff * (1.1 + spread * 2.4);
        ctx.beginPath();
        ctx.moveTo(CX, CY - EARTH_R);
        ctx.bezierCurveTo(CX + tailReach, CY - EARTH_R * (1 + spread), CX + tailReach, CY + EARTH_R * (1 + spread), CX, CY + EARTH_R);
        ctx.stroke();
      }

      // 자기권계면 경계
      ctx.strokeStyle = 'rgba(56,189,248,0.35)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      ctx.moveTo(boundaryX, CY - standoff * 1.3);
      ctx.quadraticCurveTo(boundaryX - standoff * 0.5, CY, boundaryX, CY + standoff * 1.3);
      ctx.stroke();
      ctx.setLineDash([]);

      // 태양풍 입자
      const visible = Math.round(PARTICLES * (0.3 + wind * 0.7));
      const list = particlesRef.current;
      for (let i = 0; i < list.length; i += 1) {
        const p = list[i];
        const speed = p.v * (1 + wind * 2.2);
        p.x += speed;
        // 경계 부근에서 휘어짐
        const dyFromAxis = p.y - CY;
        const boundaryHere = boundaryX - Math.pow(dyFromAxis / standoff, 2) * standoff * 0.5;
        const leaks = field < 0.28 && Math.abs(dyFromAxis) < EARTH_R * 1.2;
        if (p.x > boundaryHere && p.x < CX && !leaks) {
          p.y += dyFromAxis >= 0 ? speed * 0.9 : -speed * 0.9;  // 극 쪽/바깥으로 밀림
        }
        if (p.x > WIDTH + 10 || p.y < -10 || p.y > HEIGHT + 10) {
          p.x = -10; p.y = Math.random() * HEIGHT; p.v = 0.6 + Math.random() * 0.8;
        }
        if (i >= visible) continue;
        const hitEarth = Math.hypot(p.x - CX, p.y - CY) < EARTH_R + 2;
        ctx.fillStyle = leaks && hitEarth ? '#f87171' : 'rgba(253,224,71,0.9)';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 1.8, 0, Math.PI * 2);
        ctx.fill();
      }

      // 태양(왼쪽)
      const sun = ctx.createRadialGradient(20, CY, 6, 20, CY, 60);
      sun.addColorStop(0, 'rgba(253,224,71,0.6)');
      sun.addColorStop(1, 'rgba(253,224,71,0)');
      ctx.fillStyle = sun;
      ctx.fillRect(0, CY - 80, 100, 160);

      // 지구
      const earth = ctx.createRadialGradient(CX - 16, CY - 16, 8, CX, CY, EARTH_R);
      earth.addColorStop(0, '#38bdf8');
      earth.addColorStop(1, '#0b3b6f');
      ctx.fillStyle = earth;
      ctx.beginPath();
      ctx.arc(CX, CY, EARTH_R, 0, Math.PI * 2);
      ctx.fill();

      // 오로라(양극)
      if (aurora > 0.02) {
        const glow = (0.35 + 0.2 * Math.sin(t * 0.06)) * aurora;
        [-1, 1].forEach((dir) => {
          ctx.save();
          ctx.globalAlpha = glow;
          const gy = CY + dir * EARTH_R * 0.85;
          const ag = ctx.createRadialGradient(CX, gy, 2, CX, gy, 34);
          ag.addColorStop(0, 'rgba(74,222,128,0.9)');
          ag.addColorStop(1, 'rgba(74,222,128,0)');
          ctx.fillStyle = ag;
          ctx.beginPath();
          ctx.ellipse(CX, gy, 30, 14, 0, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
        });
      }

      // 라벨
      ctx.font = '600 12px sans-serif';
      ctx.fillStyle = 'rgba(253,224,71,0.9)';
      ctx.textAlign = 'left';
      ctx.fillText('☀ 태양풍', 8, CY - 90);
      ctx.fillStyle = 'rgba(147,197,253,0.9)';
      ctx.fillText('자기권계면', boundaryX - 78, CY - standoff * 1.3 - 6);
      ctx.textAlign = 'right';
      ctx.fillText('자기꼬리', WIDTH - 8, CY - 8);
      if (aurora > 0.2) {
        ctx.fillStyle = '#86efac';
        ctx.textAlign = 'center';
        ctx.fillText('오로라', CX, CY - EARTH_R - 24);
      }

      rafRef.current = requestAnimationFrame(render);
    };

    rafRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  return (
    <canvas ref={canvasRef} width={WIDTH} height={HEIGHT} className="w-full h-full max-h-full object-contain" />
  );
}

