function displayToLayer(display: number): AtmosphereLayer {
  return atmosphereLayers.find((l) => display >= l.displayStart && display <= l.displayEnd)
    ?? atmosphereLayers[atmosphereLayers.length - 1];
}
function displayToKm(display: number): number {
  const layer = displayToLayer(display);
