                >
                  <span>{option}</span>
                  {answered && isCorrect && <Check className="w-5 h-5 text-emerald-400" />}
                  {answered && isPicked && !isCorrect && <X className="w-5 h-5 text-red-400" />}
                </button>
              );
            })}
          </div>
          {answered && (
            <div className="mt-4 rounded-xl bg-sky-500/10 border border-sky-400/20 p-4">
              <p className="text-sm text-slate-200 leading-relaxed"><b className="text-sky-200">해설 · </b>{question.explanation}</p>
            </div>
          )}
        </div>

        {/* 이동 */}
        <div className="flex items-center justify-between mt-4">
          <button
            onClick={() => setIndex(Math.max(0, index - 1))}
            disabled={index === 0}
            className="flex items-center gap-1.5 px-4 py-2.5 rounded-xl bg-white/5 text-slate-300 font-semibold disabled:opacity-30 hover:bg-white/10 transition-colors"
          >
            <ChevronLeft className="w-4 h-4" /> 이전
          </button>
          {isLast ? (
            <button
              onClick={finish}
              disabled={!answered}
              className="flex items-center gap-1.5 px-5 py-2.5 rounded-xl bg-emerald-500 text-slate-900 font-bold disabled:opacity-30 hover:bg-emerald-400 transition-colors"
            >
              <Trophy className="w-4 h-4" /> 결과 보기
            </button>
          ) : (
            <button
              onClick={() => setIndex(index + 1)}
              disabled={!answered}
              className="flex items-center gap-1.5 px-5 py-2.5 rounded-xl bg-sky-500 text-slate-900 font-bold disabled:opacity-30 hover:bg-sky-400 transition-colors"
            >
              다음 <ChevronRight className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
